#include <odyssey.h>
#include <tests/odyssey_test.h>

#include <od_memory.h>
#include <autoconf.h>

#define HEADER                                \
	"# Do not edit this file manually!\n" \
	"# It is overwritten by ALTER SYSTEM.\n"

static void apply_ok(const char *old_text, const char *key, const char *line,
		     const char *expected)
{
	char *result = od_autoconf_apply(old_text, key, line);
	test(result != NULL);
	if (strcmp(result, expected) != 0) {
		fprintf(stderr,
			"apply_ok failed: key=[%s] line=[%s]\n"
			"--- old:\n%s\n--- expected:\n%s\n--- got:\n%s\n",
			key ? key : "(null)", line ? line : "(null)", old_text,
			expected, result);
		abort();
	}
	od_free(result);
}

static void test_autoconf_set_empty(void)
{
	apply_ok("", "workers", "workers 4", HEADER "workers 4\n");
}

static void test_autoconf_set_replaces(void)
{
	apply_ok("workers 4\n", "workers", "workers 8",
		 "# workers 4\n"
		 "workers 8\n");
}

static void test_autoconf_set_keeps_history(void)
{
	apply_ok(HEADER "# workers 4\n"
			"workers 8\n",
		 "workers", "workers 16",
		 HEADER "# workers 4\n"
			"# workers 8\n"
			"workers 16\n");
}

static void test_autoconf_set_keeps_other_keys(void)
{
	apply_ok("log_debug yes\n"
		 "workers 4\n"
		 "availability_zone \"b\"\n",
		 "workers", "workers 8",
		 "log_debug yes\n"
		 "# workers 4\n"
		 "availability_zone \"b\"\n"
		 "workers 8\n");
}

static void test_autoconf_set_key_prefix(void)
{
	apply_ok("workers_count 4\n", "workers", "workers 8",
		 "workers_count 4\n"
		 "workers 8\n");
	apply_ok("worker 4\n", "workers", "workers 8",
		 "worker 4\n"
		 "workers 8\n");
	/* the key is the whole first word, not a prefix of the line */
	apply_ok("workers\"4\"\n", "workers", "workers 8",
		 "# workers\"4\"\n"
		 "workers 8\n");
}

static void test_autoconf_set_leading_whitespace(void)
{
	apply_ok("  workers 4\n"
		 "\tworkers 5\n",
		 "workers", "workers 8",
		 "#   workers 4\n"
		 "# \tworkers 5\n"
		 "workers 8\n");
}

static void test_autoconf_set_inline_comment(void)
{
	apply_ok("workers 4 # old\n", "workers", "workers 8",
		 "# workers 4 # old\n"
		 "workers 8\n");
}

static void test_autoconf_set_duplicates(void)
{
	apply_ok("workers 4\n"
		 "log_debug yes\n"
		 "workers 5\n",
		 "workers", "workers 8",
		 "# workers 4\n"
		 "log_debug yes\n"
		 "# workers 5\n"
		 "workers 8\n");
}

static void test_autoconf_set_no_trailing_newline(void)
{
	apply_ok("workers 4", "workers", "workers 8",
		 "# workers 4\n"
		 "workers 8\n");
	apply_ok("log_debug yes", "workers", "workers 8",
		 "log_debug yes\n"
		 "workers 8\n");
}

static void test_autoconf_keeps_comments_and_blank_lines(void)
{
	apply_ok("# workers 4\n"
		 "\n"
		 "   # workers 5\n"
		 "\n",
		 "workers", "workers 8",
		 "# workers 4\n"
		 "\n"
		 "   # workers 5\n"
		 "\n"
		 "workers 8\n");
}

static void test_autoconf_reset(void)
{
	apply_ok("workers 4\n"
		 "log_debug yes\n",
		 "workers", NULL,
		 "# workers 4\n"
		 "log_debug yes\n");
	/* resetting an absent key leaves the text intact */
	apply_ok("log_debug yes\n", "workers", NULL, "log_debug yes\n");
	apply_ok("", "workers", NULL, HEADER);
}

static void test_autoconf_reset_all(void)
{
	apply_ok("# hdr\n"
		 "workers 4\n"
		 "\n"
		 "  log_debug yes\n"
		 "# workers 2\n",
		 NULL, NULL,
		 "# hdr\n"
		 "# workers 4\n"
		 "\n"
		 "#   log_debug yes\n"
		 "# workers 2\n");
	apply_ok("", NULL, NULL, HEADER);
}

static void test_autoconf_repeated_changes(void)
{
	char *text = od_autoconf_apply("", "workers", "workers 4");
	test(text != NULL);

	char *next = od_autoconf_apply(text, "log_debug", "log_debug yes");
	test(next != NULL);
	od_free(text);
	text = next;

	next = od_autoconf_apply(text, "workers", "workers 8");
	test(next != NULL);
	od_free(text);
	text = next;

	next = od_autoconf_apply(text, NULL, NULL);
	test(next != NULL);
	od_free(text);
	text = next;

	test(strcmp(text, HEADER "# workers 4\n"
				 "# log_debug yes\n"
				 "# workers 8\n") == 0);
	od_free(text);
}

void odyssey_test_autoconf(void)
{
	test_autoconf_set_empty();
	test_autoconf_set_replaces();
	test_autoconf_set_keeps_history();
	test_autoconf_set_keeps_other_keys();
	test_autoconf_set_key_prefix();
	test_autoconf_set_leading_whitespace();
	test_autoconf_set_inline_comment();
	test_autoconf_set_duplicates();
	test_autoconf_set_no_trailing_newline();
	test_autoconf_keeps_comments_and_blank_lines();
	test_autoconf_reset();
	test_autoconf_reset_all();
	test_autoconf_repeated_changes();
}
